import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        department TEXT,
        active INTEGER DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        actor TEXT,
        detail TEXT
    )''')
    db.commit()
    db.close()

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({"status": "ok"})

@app.route('/api/users/lookup', methods=['GET'])
def user_lookup():
    """Lookup users by department and role for internal directory.
    Supports flexible filtering for HR dashboard integration."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    active_only = request.args.get('active', '1')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE active = " + active_only

    if department:
        base_query += " AND department = '" + department + "'"
    if role:
        base_query += " AND role = '" + role + "'"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({"users": users, "count": len(users)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({"error": "Internal error"}), 500

@app.route('/api/users/search', methods=['POST'])
def user_search():
    """Advanced search endpoint for admin panel."""
    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    search_term = data.get('query', '')
    field = data.get('field', 'username')

    # Restrict searchable fields
    allowed_fields = ['username', 'email', 'department', 'role']
    if field not in allowed_fields:
        return jsonify({"error": "Invalid field"}), 400

    # Note: search_term is still user-controlled
    query = f"SELECT id, username, email, role, department FROM users WHERE {field} LIKE '%{search_term}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({"users": users, "count": len(users)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({"error": "Internal error"}), 500

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries. Requires HMAC signature."""
    sig = request.headers.get('X-Audit-Signature', '')
    timestamp = request.headers.get('X-Timestamp', '')

    expected = hmac.new(SECRET_KEY.encode(), timestamp.encode(), hashlib.sha256).hexdigest() if timestamp else ''
    if not hmac.compare_digest(sig, expected):
        return jsonify({"error": "Unauthorized"}), 403

    limit = request.args.get('limit', '50')
    query = f"SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT {limit}"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({"entries": [dict(r) for r in results]})
    except Exception as e:
        return jsonify({"error": "Internal error"}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
